JsonValue id(std::string_view value) { return s(std::string(value)); }
JsonValue point(core::WorldPointI p) { JsonObject x; put(x,"x",n(p.x)); put(x,"y",n(p.y)); return o(std::move(x)); }
JsonValue area(world::AabbI p) { JsonObject x; put(x,"x",n(p.x)); put(x,"y",n(p.y)); put(x,"width",n(p.width)); put(x,"height",n(p.height)); return o(std::move(x)); }
std::string facing(gameplay::FacingDirection v) { switch(v){case gameplay::FacingDirection::down:return "down";case gameplay::FacingDirection::up:return "up";case gameplay::FacingDirection::left:return "left";case gameplay::FacingDirection::right:return "right";} return "down"; }
