struct Reader { std::vector<AuthoredMapDiagnostic> d; void error(const JsonValue& v,std::string path,std::string code,std::string msg){d.push_back({AuthoredMapDiagnosticStage::decode,std::move(code),std::move(msg),std::move(path),v.span.begin.line,v.span.begin.column});} };
