bool definitionId(const JsonValue& v,Reader& r,const std::string& p,simulation::DefinitionId& out){std::string x;if(!text(v,r,p,x))return false;out=simulation::DefinitionId{std::move(x)};return true;}
bool mapId(const JsonValue& v,Reader& r,const std::string& p,simulation::MapId& out){std::string x;if(!text(v,r,p,x))return false;out=simulation::MapId{std::move(x)};return true;}
bool facingRead(const JsonValue& v,Reader& r,const std::string& p,gameplay::FacingDirection& out){std::string x;if(!text(v,r,p,x))return false;if(x=="down")out=gameplay::FacingDirection::down;else if(x=="up")out=gameplay::FacingDirection::up;else if(x=="left")out=gameplay::FacingDirection::left;else if(x=="right")out=gameplay::FacingDirection::right;else{r.error(v,p,"unknown_enum","unknown facing direction");return false;}return true;}
JsonValue placementId(std::uint64_t v){return u(v);}
const char* triggerName(WorldTriggerKind v){switch(v){case WorldTriggerKind::mapEntered:return "mapEntered";case WorldTriggerKind::regionEntered:return "regionEntered";case WorldTriggerKind::regionExited:return "regionExited";case WorldTriggerKind::encounterStarted:return "encounterStarted";case WorldTriggerKind::encounterCompleted:return "encounterCompleted";case WorldTriggerKind::objectOpened:return "objectOpened";}return "mapEntered";}
const char* conditionName(WorldConditionKind v){switch(v){case WorldConditionKind::flagSet:return "flagSet";case WorldConditionKind::flagNotSet:return "flagNotSet";case WorldConditionKind::encounterCompleted:return "encounterCompleted";case WorldConditionKind::encounterNotCompleted:return "encounterNotCompleted";case WorldConditionKind::doorState:return "doorState";}return "flagSet";}
const char* actionName(WorldActionKind v){switch(v){case WorldActionKind::setFlag:return "setFlag";case WorldActionKind::clearFlag:return "clearFlag";case WorldActionKind::startEncounter:return "startEncounter";case WorldActionKind::setDoorState:return "setDoorState";}return "setFlag";}
const char* doorName(DoorState v){switch(v){case DoorState::locked:return "locked";case DoorState::closed:return "closed";case DoorState::open:return "open";}return "closed";}
void addAllowed(const JsonObject& x,Reader& r,const std::string& p,std::initializer_list<std::string_view> keys){for(const auto& m:x){bool found=false;for(auto k:keys)if(m.first==k)found=true;if(!found)r.error(m.second,p+"."+m.first,"unknown_field","unknown field");}}
